import { DatePipe } from '@angular/common';
import {
    Component,
    DestroyRef,
    computed,
    inject,
    input,
    linkedSignal,
    resource,
    signal,
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatRippleModule } from '@angular/material/core';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
import { MatTooltipModule } from '@angular/material/tooltip';
import { ActivatedRoute, Router } from '@angular/router';
import { i18n } from '@placeos/common';
import { IconComponent, TranslatePipe } from '@placeos/components';
import { addDays, isSameDay, startOfDay } from 'date-fns';
import { SignagePlaylistService } from '../playlists/signage-playlist.service';
import { GroupBreadcrumbsComponent } from '../shared/group-breadcrumbs.component';
import { NavFooterComponent } from '../shared/nav-footer.component';
import { NavSidebarComponent } from '../shared/nav-sidebar.component';
import { SignageInventoryService } from '../signage-inventory.service';
import { ScheduleTimelineComponent } from './schedule-timeline.component';
import {
    ScheduleTimelineRow,
    buildDayTimelineBlocks,
    buildDisplayScheduleAssignments,
    buildZoneScheduleAssignments,
} from './signage-schedule.util';

const TAB_QUERY_PARAM = 'tab';

function parseScheduleTab(value: string | null): 'displays' | 'zones' {
    return value === 'zones' ? 'zones' : 'displays';
}

/** Rows whose name, description, zones, playlists or sources include the search term */
function filterRows(rows: ScheduleTimelineRow[], search_term: string) {
    const search = search_term.trim().toLowerCase();
    return search
        ? rows.filter((row) => row.search_index.includes(search))
        : rows;
}

@Component({
    selector: 'schedules-section',
    template: `
        <div class="bg-base-200 absolute inset-0 flex flex-col sm:flex-row">
            <nav-sidebar class="sm:h-full" />
            <div class="flex min-h-0 flex-1 flex-col overflow-hidden">
                <div
                    class="bg-base-100 border-base-300 relative z-10 border-b px-4 py-3"
                >
                    <div
                        class="flex flex-col gap-3 sm:flex-row sm:items-center"
                    >
                        <div class="min-w-0 flex-1">
                            <h2 class="text-lg font-semibold">
                                {{
                                    'SIGNAGE_MANAGER.NAV_SCHEDULES' | translate
                                }}
                            </h2>
                            <group-breadcrumbs />
                        </div>
                        <div
                            class="bg-base-content/5 flex max-w-52 overflow-hidden rounded-lg p-1"
                            role="tablist"
                            [attr.aria-label]="
                                'SIGNAGE_MANAGER.SCHEDULE_TYPES' | translate
                            "
                            (keydown)="onTabKeydown($event)"
                        >
                            <button
                                type="button"
                                role="tab"
                                id="schedules-tab-displays"
                                aria-controls="schedules-panel"
                                [attr.tabindex]="
                                    view_tab() === 'displays' ? 0 : -1
                                "
                                class="flex rounded-md p-2 font-medium transition-all duration-150"
                                [class.bg-base-100]="view_tab() === 'displays'"
                                [class.shadow-sm]="view_tab() === 'displays'"
                                [class.text-primary]="view_tab() === 'displays'"
                                [class.opacity-50]="view_tab() !== 'displays'"
                                [attr.aria-selected]="view_tab() === 'displays'"
                                (click)="setViewTab('displays')"
                            >
                                <div class="px-1">
                                    {{
                                        'SIGNAGE_MANAGER.NAV_DISPLAYS'
                                            | translate
                                    }}
                                </div>
                                <div
                                    class="bg-base-content/5 h-6 min-w-6 rounded-full p-1 text-xs opacity-60"
                                >
                                    {{ display_total() }}
                                </div>
                            </button>
                            <button
                                type="button"
                                role="tab"
                                id="schedules-tab-zones"
                                aria-controls="schedules-panel"
                                [attr.tabindex]="
                                    view_tab() === 'zones' ? 0 : -1
                                "
                                class="flex rounded-md p-2 font-medium transition-all duration-150"
                                [class.bg-base-100]="view_tab() === 'zones'"
                                [class.shadow-sm]="view_tab() === 'zones'"
                                [class.text-primary]="view_tab() === 'zones'"
                                [class.opacity-50]="view_tab() !== 'zones'"
                                [attr.aria-selected]="view_tab() === 'zones'"
                                (click)="setViewTab('zones')"
                            >
                                <div class="px-1">
                                    {{
                                        'SIGNAGE_MANAGER.NAV_ZONES' | translate
                                    }}
                                </div>
                                <div
                                    class="bg-base-content/5 h-6 min-w-6 rounded-full p-1 text-xs opacity-60"
                                >
                                    {{ zone_total() }}
                                </div>
                            </button>
                        </div>
                    </div>
                    <div
                        class="mt-2.5 flex flex-col gap-2 md:flex-row md:items-center md:justify-between"
                    >
                        <div class="flex items-center gap-0.5">
                            <button
                                icon
                                type="button"
                                matRipple
                                [matTooltip]="
                                    'SIGNAGE_MANAGER.PREVIOUS_DAY' | translate
                                "
                                (click)="previousDay()"
                                [attr.aria-label]="
                                    'SIGNAGE_MANAGER.SHOW_PREVIOUS_DAY'
                                        | translate
                                "
                            >
                                <icon>chevron_left</icon>
                            </button>
                            <button
                                icon
                                type="button"
                                matRipple
                                [matTooltip]="'COMMON.TODAY' | translate"
                                (click)="goToToday()"
                                [attr.aria-label]="
                                    'SIGNAGE_MANAGER.SHOW_TODAY' | translate
                                "
                            >
                                <icon>today</icon>
                            </button>
                            <button
                                icon
                                type="button"
                                matRipple
                                [matTooltip]="
                                    'SIGNAGE_MANAGER.NEXT_DAY' | translate
                                "
                                (click)="nextDay()"
                                [attr.aria-label]="
                                    'SIGNAGE_MANAGER.SHOW_NEXT_DAY' | translate
                                "
                            >
                                <icon>chevron_right</icon>
                            </button>
                            <div class="ml-1.5">
                                <div class="text-sm leading-tight font-medium">
                                    {{
                                        selected_date()
                                            | date: 'EEEE, d MMMM yyyy'
                                    }}
                                </div>
                                <div class="text-base-content/45 text-[11px]">
                                    {{ selected_date() | date: 'EEE' }}
                                </div>
                            </div>
                        </div>
                        <mat-form-field
                            appearance="outline"
                            class="no-subscript min-w-1/2"
                        >
                            <icon matPrefix class="text-2xl">search</icon>
                            <input
                                matInput
                                type="search"
                                [(ngModel)]="search_term"
                                [placeholder]="search_placeholder() | translate"
                                [attr.aria-label]="
                                    search_placeholder() | translate
                                "
                            />
                            @if (search_term()) {
                                <button
                                    icon
                                    matSuffix
                                    type="button"
                                    matRipple
                                    (click)="clearSearch()"
                                    [attr.aria-label]="
                                        'SIGNAGE_MANAGER.CLEAR_SCHEDULE_SEARCH'
                                            | translate
                                    "
                                >
                                    <icon>close</icon>
                                </button>
                            }
                        </mat-form-field>
                    </div>
                </div>

                <div class="min-h-0 flex-1 p-2">
                    <div
                        id="schedules-panel"
                        role="tabpanel"
                        class="bg-base-100 border-base-300 flex h-full min-h-0 flex-col overflow-hidden rounded-lg border"
                        [attr.aria-labelledby]="'schedules-tab-' + view_tab()"
                    >
                        @if (inventory_error()) {
                            <div
                                class="text-base-content/60 flex flex-1 flex-col items-center justify-center gap-3"
                                role="alert"
                            >
                                <icon class="text-error text-4xl">error</icon>
                                <p class="text-sm">
                                    {{ 'COMMON.LOAD_ERROR' | translate }}
                                </p>
                                <button
                                    btn
                                    matRipple
                                    type="button"
                                    class="inverse"
                                    (click)="reload()"
                                >
                                    {{ 'COMMON.RETRY' | translate }}
                                </button>
                            </div>
                        } @else if (!rows().length && inventory_loading()) {
                            <div
                                class="flex flex-1 flex-col items-center justify-center gap-3 opacity-70"
                            >
                                <mat-spinner diameter="32" />
                                <p class="text-sm">
                                    {{ 'COMMON.LOADING' | translate }}
                                </p>
                            </div>
                        } @else if (!rows().length) {
                            <div
                                class="text-base-content/40 flex flex-1 flex-col items-center justify-center gap-3"
                            >
                                <icon class="text-4xl">
                                    {{
                                        view_tab() === 'displays'
                                            ? 'tv_off'
                                            : 'layers_clear'
                                    }}
                                </icon>
                                <p class="text-sm">
                                    {{
                                        (search_term()
                                            ? 'SIGNAGE_MANAGER.NO_SCHEDULES_MATCH'
                                            : view_tab() === 'displays'
                                              ? 'SIGNAGE_MANAGER.NO_DISPLAYS_AVAILABLE'
                                              : 'SIGNAGE_MANAGER.NO_ZONES_AVAILABLE'
                                        ) | translate
                                    }}
                                </p>
                            </div>
                        } @else {
                            <schedule-timeline
                                [rows]="rows()"
                                [view_tab]="view_tab()"
                                [current_minutes]="current_minutes()"
                                [show_current_time]="show_current_time()"
                                [playlist_approval_status]="
                                    playlist_approval_status()
                                "
                            />
                        }
                    </div>
                </div>
            </div>
            <nav-footer />
        </div>
    `,
    styles: [
        `
            :host {
                display: flex;
                flex-direction: column;
                height: 100%;
            }
        `,
    ],
    imports: [
        DatePipe,
        FormsModule,
        MatRippleModule,
        MatTooltipModule,
        IconComponent,
        NavSidebarComponent,
        NavFooterComponent,
        GroupBreadcrumbsComponent,
        ScheduleTimelineComponent,
        MatFormFieldModule,
        MatInputModule,
        MatProgressSpinnerModule,
        TranslatePipe,
    ],
})
export class SchedulesSectionComponent {
    private readonly _inventory_service = inject(SignageInventoryService);
    private readonly _playlist_service = inject(SignagePlaylistService);
    private readonly _route = inject(ActivatedRoute);
    private readonly _router = inject(Router);
    private readonly _destroy_ref = inject(DestroyRef);

    public readonly tab = input<string | null>(null);
    /** Follows the route, and changes at once when users pick a tab */
    public readonly view_tab = linkedSignal(() => parseScheduleTab(this.tab()));
    public readonly search_term = signal('');
    public readonly selected_date = signal(startOfDay(new Date()));
    public readonly current_time = signal(new Date());

    // The service lists only hold the pages loaded so far, so load every
    // display, zone and playlist in the group.
    private readonly _inventory = resource({
        params: () => this._inventory_service.inventory_key(),
        loader: () => this._inventory_service.loadSignageInventory(),
    });
    private readonly _inventory_value = computed(() =>
        this._inventory.hasValue() ? this._inventory.value() : undefined,
    );
    private readonly _playlists = computed(
        () => this._inventory_value()?.playlists || [],
    );
    private readonly _displays = computed(
        () => this._inventory_value()?.displays || [],
    );
    private readonly _zones = computed(
        () => this._inventory_value()?.zones || [],
    );

    public readonly inventory_loading = this._inventory.isLoading;
    public readonly inventory_error = computed(() => !!this._inventory.error());

    public readonly playlist_approval_status =
        this._playlist_service.playlist_approval_status;
    public readonly display_total = computed(() => this._displays().length);
    public readonly zone_total = computed(() => this._zones().length);
    public readonly search_placeholder = computed(() =>
        this.view_tab() === 'displays'
            ? 'SIGNAGE_MANAGER.SEARCH_DISPLAYS_ZONES_PLAYLISTS'
            : 'SIGNAGE_MANAGER.SEARCH_ZONES_PLAYLISTS',
    );
    public readonly current_minutes = computed(() => {
        const now = this.current_time();
        return now.getHours() * 60 + now.getMinutes();
    });
    public readonly show_current_time = computed(() =>
        isSameDay(this.selected_date(), this.current_time()),
    );

    private readonly _all_display_rows = computed<ScheduleTimelineRow[]>(() => {
        const playlists = this._playlists();
        const zones = this._zones();
        const date = this.selected_date();
        const zone_names = new Map(
            zones.map((zone) => [zone.id, zone.display_name || zone.name]),
        );

        return this._displays().map((display) => {
            const assignments = buildDisplayScheduleAssignments(
                display,
                zones,
                playlists,
            );
            const { blocks, lane_count } = buildDayTimelineBlocks(
                assignments,
                date,
            );
            const zone_count = (display.zones || []).length;
            const zone_label = zone_count
                ? ` · ${i18n(
                      'SIGNAGE_MANAGER.ZONE_COUNT_LABEL',
                      {
                          count: zone_count,
                      },
                      zone_count,
                  )}`
                : '';
            const search_index = [
                display.display_name || display.name,
                display.description || '',
                ...(display.zones || []).map((id) => zone_names.get(id) || ''),
                ...assignments.map((item) => item.playlist.name),
                ...assignments.map((item) => item.source_label || ''),
            ]
                .join(' ')
                .toLowerCase();
            return {
                id: display.id,
                name: display.display_name || display.name,
                subtitle: `${i18n(
                    'SIGNAGE_MANAGER.PLAYLIST_COUNT_LABEL',
                    {
                        count: assignments.length,
                    },
                    assignments.length,
                )}${zone_label}`,
                icon: 'tv',
                route: ['/displays', display.id],
                blocks,
                lane_count,
                search_index,
                signage_last_seen: display.signage_last_seen,
            };
        });
    });

    private readonly _all_zone_rows = computed<ScheduleTimelineRow[]>(() => {
        const playlists = this._playlists();
        const displays = this._displays();
        const date = this.selected_date();

        return this._zones().map((zone) => {
            const assignments = buildZoneScheduleAssignments(zone, playlists);
            const { blocks, lane_count } = buildDayTimelineBlocks(
                assignments,
                date,
            );
            const display_count = displays.filter((display) =>
                display.zones?.includes(zone.id),
            ).length;
            const search_index = [
                zone.display_name || zone.name,
                zone.description || '',
                ...assignments.map((item) => item.playlist.name),
            ]
                .join(' ')
                .toLowerCase();
            return {
                id: zone.id,
                name: zone.display_name || zone.name,
                subtitle: `${i18n(
                    'SIGNAGE_MANAGER.PLAYLIST_COUNT_LABEL',
                    {
                        count: assignments.length,
                    },
                    assignments.length,
                )} · ${i18n(
                    'SIGNAGE_MANAGER.DISPLAY_COUNT_LABEL',
                    {
                        count: display_count,
                    },
                    display_count,
                )}`,
                icon: 'layers',
                route: ['/zones', zone.id],
                blocks,
                lane_count,
                search_index,
            };
        });
    });

    // Filter in separate signals so typing does not rebuild the blocks
    public readonly display_rows = computed(() =>
        filterRows(this._all_display_rows(), this.search_term()),
    );
    public readonly zone_rows = computed(() =>
        filterRows(this._all_zone_rows(), this.search_term()),
    );

    public readonly rows = computed(() =>
        this.view_tab() === 'displays' ? this.display_rows() : this.zone_rows(),
    );

    constructor() {
        const timer = setInterval(
            () => this.current_time.set(new Date()),
            60_000,
        );
        this._destroy_ref.onDestroy(() => clearInterval(timer));
    }

    /** Load the schedules again after an error */
    public reload() {
        this._inventory.reload();
    }

    public clearSearch() {
        this.search_term.set('');
    }

    public setViewTab(tab: 'displays' | 'zones') {
        if (tab === this.view_tab()) return;
        this.view_tab.set(tab);
        void this._router.navigate([], {
            relativeTo: this._route,
            queryParams: { [TAB_QUERY_PARAM]: tab },
            queryParamsHandling: 'merge',
            replaceUrl: true,
        });
    }

    /** Move between the tabs with the arrow, Home and End keys */
    public onTabKeydown(event: KeyboardEvent) {
        const keys: Record<string, 'displays' | 'zones'> = {
            ArrowLeft: 'displays',
            Home: 'displays',
            ArrowRight: 'zones',
            End: 'zones',
        };
        const tab = keys[event.key];
        if (!tab) return;
        event.preventDefault();
        this.setViewTab(tab);
        document.getElementById(`schedules-tab-${tab}`)?.focus();
    }

    public previousDay() {
        this.selected_date.update((date) => addDays(date, -1));
    }

    public nextDay() {
        this.selected_date.update((date) => addDays(date, 1));
    }

    public goToToday() {
        this.selected_date.set(startOfDay(new Date()));
    }
}
